#!/bin/sh
# PreToolUse hook for Kiro CLI agents: the pending tool call arrives as JSON on stdin.
# EF Core migrations are generated by `dotnet ef` (a shell command), so a file-tool write
# into Migrations/ is a hand edit. Exit code 2 blocks the call; stderr is shown to the agent.
if grep -Eq '"path"[[:space:]]*:[[:space:]]*"[^"]*Migrations(/|\\\\)[^"/\\]+\.cs"'; then
  echo "Blocked: files under Migrations/ are generated. Do not edit them by hand; create a new migration with 'dotnet ef migrations add <Name>' instead. Only edit a migration manually if the user explicitly asked for it." 1>&2
  exit 2
fi
exit 0
